type Service interface{ Do(ctx context.Context, req string) (string, error) }

type cached struct {
    next Service
    mu   sync.Mutex
    m    map[string]string
}

func (c *cached) Do(ctx context.Context, req string) (string, error) {
    c.mu.Lock()
    defer c.mu.Unlock()
    if v, ok := c.m[req]; ok { return v, nil }
    v, err := c.next.Do(ctx, req)
    if err == nil { c.m[req] = v }
    return v, err
}
